  // ---- the paper: kept in the book, so the file prints the same way anywhere ----
  const PAPERS = { A3: { w: 297, h: 420 }, A4: { w: 210, h: 297 }, A5: { w: 148, h: 210 }, B4: { w: 257, h: 364 }, B5: { w: 182, h: 257 }, Letter: { w: 215.9, h: 279.4 }, Legal: { w: 215.9, h: 355.6 } };
